"""The grading store for the Corringham oyster beds."""

GRADES = {}
LOTS = {}


def grade_oyster(oyster):
    GRADES[oyster] = "graded"
    return oyster


def grade_oysters(day):
    """Tag a whole day's crop as one lot."""
    LOTS[day] = True
    return day
